from pathlib import Path
import json,hashlib,base64,html
R=Path('.');base='https://vivreengeorgie.com/'
pages=[
{'slug':'creation-entreprise-georgie','title':'Créer une entreprise en Géorgie : LLC et Small Business','desc':'Création d’entreprise en Géorgie en français ou espagnol : choix LLC ou Small Business, documents, procuration, comptabilité et accompagnement.','tag':'ENTREPRENDRE EN GÉORGIE','lead':'Vivre en Géorgie coordonne la création de votre entreprise avec les professionnels locaux : choix du cadre, préparation du dossier, immatriculation et suivi comptable selon la prestation convenue. Vous pouvez préparer votre projet en français ou en espagnol, sur place ou à distance selon les démarches.','sections':[
('LLC ou entrepreneur individuel : partir de votre activité','<p>Le choix ne se résume pas à un taux d’impôt. Nous commençons par votre activité réelle, vos clients, votre chiffre d’affaires prévu, vos associés éventuels et votre pays de résidence. Ces éléments permettent au professionnel compétent de vérifier le cadre adapté avant le dépôt du dossier.</p><div class="cards"><article><h3>LLC</h3><p>Une société distincte de son dirigeant, à étudier notamment pour un projet avec associés. Le régime général vise les distributions et opérations assimilées : « 0 % sur les bénéfices conservés » ne signifie pas une exonération de toutes les opérations.</p></article><article><h3>Small Business</h3><p>Un statut fiscal pour l’entrepreneur individuel éligible, pas une forme de société. Le taux de 1 % concerne le revenu imposable éligible. L’activité, la source des revenus et les seuils doivent être vérifiés.</p></article></div>'),
('Ce que comprend notre accompagnement','<ol><li><strong>Cadrer le projet.</strong> Nous recueillons votre activité, vos besoins bancaires et votre organisation pour faire examiner le statut adapté.</li><li><strong>Préparer les pièces.</strong> Nous vous communiquons les documents et les formalités de traduction ou de légalisation nécessaires à votre situation.</li><li><strong>Coordonner la création.</strong> Nous organisons les échanges avec les professionnels intervenant dans l’immatriculation.</li><li><strong>Préparer la suite.</strong> Compte bancaire professionnel, déclarations fiscales et comptabilité sont organisés selon la formule convenue.</li></ol>'),
('Quels documents préparer ?','<p>Votre passeport est le point de départ. Préparez aussi une description précise de votre activité, vos coordonnées, votre résidence fiscale et, si le projet comporte plusieurs personnes, les informations sur les associés. La liste définitive vous est indiquée après étude ; elle peut inclure des pièces complémentaires.</p><p>Évitez d’envoyer des copies de pièces d’identité dans votre premier message. Décrivez d’abord votre projet pour convenir des modalités de transmission appropriées.</p>'),
('Créer à distance par procuration','<p>Notre avocate peut vous représenter pour les démarches qui le permettent. Nous coordonnons le contenu de la procuration et les formalités requises avant son utilisation. Une création à distance ne signifie pas que chaque démarche bancaire sera automatiquement réalisable à distance.</p>'),
('Fiscalité : les conditions à comprendre','<p>Le Small Business est généralement imposé à 1 %, puis à 3 % dans les conditions de dépassement du seuil ordinaire de 500 000 GEL. Des règles particulières existent, notamment pour certaines activités touristiques. TVA et résidence fiscale s’examinent séparément. Pour une LLC au régime général, le traitement des distributions et des dividendes doit être chiffré avec le comptable.</p><p>Référence : <a href="https://matsne.gov.ge/en/document/view/1043717">Code fiscal géorgien, notamment articles 88 à 92 et 97 à 98</a>. Le statut géorgien ne détermine pas à lui seul vos obligations dans votre pays de résidence.</p>')],
'qa':[('Peut-on créer son entreprise en Géorgie sans venir sur place ?','Certaines démarches peuvent être réalisées par procuration avec notre avocate. Les documents, traductions et éventuelles légalisations sont définis selon le dossier.'),('Le régime à 1 % s’applique-t-il à une LLC ?','Non. Le statut Small Business concerne un entrepreneur individuel éligible. Une LLC relève d’un autre cadre fiscal.'),('La comptabilité est-elle incluse ?','Nous pouvons prendre en charge la comptabilité et les déclarations fiscales. Le périmètre, la fréquence et les honoraires sont précisés dans la formule convenue.'),('Quel est le prix et le délai de création ?','Le devis et le calendrier dépendent du statut, des pièces disponibles et des démarches à distance. Ils sont précisés avant engagement, sans annoncer un délai identique pour tous les dossiers.')],
'sources':[('Registre public géorgien : démarches et services','https://www.napr.gov.ge/en'),('Code fiscal géorgien','https://matsne.gov.ge/en/document/view/1043717')]},
{'slug':'compte-bancaire-georgie','title':'Ouvrir un compte bancaire en Géorgie : accompagnement','desc':'Préparez votre compte personnel ou professionnel en Géorgie : documents, ouverture à distance, cartes et virements. Accompagnement français et espagnol.','tag':'BANQUE EN GÉORGIE','lead':'Nous vous accompagnons dans la préparation et la coordination de l’ouverture d’un compte bancaire personnel et, pour votre entreprise, professionnel en Géorgie. Le dossier est présenté à la banque, qui conserve la décision d’acceptation et définit les services accessibles.','sections':[
('Compte personnel ou professionnel : deux usages à préparer','<div class="cards"><article><h3>Compte personnel</h3><p>Pour vos besoins individuels : paiements, transferts et services bancaires disponibles selon votre profil. Nous vous aidons à préparer la démarche et à comprendre les conditions de l’offre retenue.</p></article><article><h3>Compte professionnel</h3><p>Pour l’activité de votre entreprise : encaissements, dépenses et suivi des flux. Nous coordonnons sa préparation avec la création de l’entreprise et les informations demandées sur l’activité.</p></article></div>'),
('Comment se déroule l’accompagnement ?','<ol><li><strong>Décrire les usages.</strong> Compte personnel ou professionnel, devises, pays de vos clients et fréquence des opérations.</li><li><strong>Préparer le dossier.</strong> Nous vous indiquons les pièces demandées en fonction de la banque et de votre profil.</li><li><strong>Coordonner la démarche.</strong> Nous facilitons les échanges et l’organisation du rendez-vous ou de la procédure à distance acceptée.</li><li><strong>Comparer les services.</strong> Nous vous aidons à lire les frais, limites et conditions de la carte, des transferts et de l’application.</li></ol>'),
('Quels justificatifs prévoir ?','<p>Préparez votre passeport et les informations permettant d’expliquer votre activité, votre résidence fiscale et l’usage attendu du compte. La banque peut demander des justificatifs complémentaires sur les revenus, l’origine des fonds ou les opérations prévues. Pour un compte professionnel, les informations d’immatriculation et de fonctionnement de l’entreprise complètent le dossier.</p><p>La liste précise varie selon l’établissement. Nous la confirmons pour votre dossier : posséder un passeport ne garantit pas à lui seul l’ouverture d’un compte.</p>'),
('Cartes, application et virements internationaux','<p>Selon l’offre disponible et votre éligibilité, nous vous aidons à étudier les gammes de cartes, y compris des offres Visa ou Mastercard premium. Les accès aux salons d’aéroport dépendent du programme de la carte, des quotas et des conditions applicables.</p><p>Pour les virements, nous comparons les devises, frais et limites annoncés. Une application mobile facilite la gestion, mais ne supprime pas les contrôles et demandes de justificatifs. Nous ne promettons pas des transferts illimités ni une acceptation automatique.</p>'),
('Ouverture à distance et financement','<p>Une démarche à distance peut être étudiée avec une procuration lorsque la banque et le dossier le permettent. Elle doit être confirmée avant de préparer les formalités.</p><p>Un crédit constitue une demande distincte. Nous pouvons coordonner l’étude d’un financement en fonction de votre projet et de votre situation ; le prêteur fixe les conditions et prend la décision. Pour un investissement immobilier, le dossier bancaire se prépare en parallèle de la sélection du bien.</p>')],
'qa':[('Un étranger peut-il demander un compte bancaire en Géorgie ?','Nous accompagnons la préparation de dossiers de clients étrangers. L’établissement examine chaque demande et peut demander des informations complémentaires ou la refuser.'),('L’ouverture du compte est-elle garantie ?','Non. Nous prenons en charge l’accompagnement et la coordination des démarches. La décision appartient à la banque.'),('Puis-je ouvrir le compte à distance ?','Cette possibilité doit être confirmée pour votre dossier et l’établissement choisi. Une procuration ne garantit pas que toutes les opérations pourront se faire à distance.'),('Les cartes premium et les salons sont-ils automatiquement inclus ?','Non. La gamme de carte, les frais et l’accès aux salons dépendent de l’offre retenue et de votre éligibilité. Nous vous aidons à comparer les conditions avant le choix.')],
'sources':[('Banque nationale de Géorgie : institution de supervision','https://nbg.gov.ge/en')]},
{'slug':'investir-immobilier-georgie','title':'Investir dans l’immobilier en Géorgie : Batumi et Tbilissi','desc':'Investissement immobilier à Batumi et Tbilissi : sélection des biens, étude du rendement, financement bancaire et coordination des professionnels locaux.','tag':'IMMOBILIER EN GÉORGIE','lead':'Vivre en Géorgie accompagne votre investissement immobilier à Batumi et Tbilissi : sélection du bien, comparaison des projets, étude des hypothèses de rendement et coordination du dossier de financement. La décision s’appuie sur les documents du projet, vos objectifs et votre budget.','sections':[
('Choisir un bien à partir de votre objectif','<p>Un logement pour votre usage, une location longue durée et un investissement touristique ne s’évaluent pas de la même manière. Nous partons de votre budget total, de votre horizon de détention et de votre besoin éventuel de financement avant de comparer les biens.</p><div class="cards"><article><h3>Batumi / Batoumi</h3><p>Pour un projet locatif, nous proposons d’examiner la saisonnalité, la concurrence autour du bien, les conditions de gestion et le coût de l’ameublement. Une projection annuelle doit distinguer les périodes d’occupation.</p></article><article><h3>Tbilissi / Tbilisi</h3><p>Nous comparons le quartier, les usages possibles du logement, son état et le budget des travaux. L’estimation doit être cohérente avec le mode de location envisagé et les charges du bien.</p></article></div>'),
('Notre méthode, de la sélection à la réservation','<ol><li><strong>Définir le budget complet.</strong> Prix, apport disponible, travaux, ameublement et dépenses liées au dossier.</li><li><strong>Comparer les biens.</strong> Emplacement, calendrier, promoteur, contrat et mode de gestion envisagé.</li><li><strong>Faire vérifier les pièces.</strong> Nous coordonnons les échanges avec les professionnels compétents pour les questions juridiques, comptables et bancaires.</li><li><strong>Étudier le financement.</strong> Nous préparons la mise en relation bancaire selon votre profil et le bien retenu.</li><li><strong>Accompagner la réservation.</strong> Les conditions et les intervenants sont définis avant engagement.</li></ol>'),
('Jusqu’à 12 % net : un potentiel à documenter','<p>Un potentiel pouvant aller jusqu’à 12 % net par an dépend du projet. Il ne constitue ni une moyenne de marché, ni une promesse de revenus. Avant toute décision, l’étude doit préciser les loyers attendus, l’occupation, les frais de gestion, l’entretien, les charges et la fiscalité retenue.</p><p>Nous demandons également de distinguer le rendement du bien de la rentabilité de votre apport après financement. Les intérêts, le change, les travaux imprévus et les périodes sans locataire peuvent modifier le résultat. Sans hypothèses détaillées, un pourcentage seul ne permet pas de comparer deux projets.</p>'),
('Un financement pouvant aller jusqu’à 70 %','<p>Un financement bancaire local pouvant aller jusqu’à 70 % de la valeur retenue par la banque peut être étudié selon votre situation et le projet. Il ne s’agit pas d’un accord préalable : le prêteur examine le dossier, l’apport, les revenus et le bien. La valeur retenue peut différer du prix demandé.</p><p>Le taux, la durée, la devise, les assurances et les frais doivent être intégrés au budget. Nous coordonnons l’étude ; la banque décide.</p>'),
('Fiscalité et frais : lire les conditions','<p>Le taux de 5 % concerne certaines locations résidentielles éligibles par une personne physique, sans déduction de charges. Une exonération de plus-value peut s’appliquer à une cession résidentielle après plus de deux ans de détention, sous conditions. Ces règles ne s’appliquent pas indistinctement à toutes les formes de détention et d’exploitation.</p><p>Nos frais d’accompagnement immobilier annoncés sont de 0 €. Cela ne signifie pas l’absence de tous frais d’acquisition : enregistrement, traduction, financement et prestations de tiers doivent être identifiés dans le dossier. L’acte notarié n’est pas systématique.</p><p>Consultez le <a href="https://matsne.gov.ge/en/document/view/1043717">Code fiscal géorgien, articles 81 et 82</a> et le <a href="https://www.napr.gov.ge/en">registre public géorgien</a>. Les vérifications propres au bien sont menées avec les professionnels compétents.</p>')],
'qa':[('Le rendement de 12 % est-il garanti ?','Non. C’est un potentiel dépendant du projet. Les frais, impôts et hypothèses d’occupation doivent être détaillés dans l’étude du bien.'),('Puis-je financer 70 % du prix ?','Un financement jusqu’à 70 % de la valeur retenue par la banque peut être étudié. Le montant dépend du dossier, de l’évaluation du bien et de l’accord du prêteur.'),('Quels frais faut-il prévoir en plus du prix ?','Le budget doit identifier les éventuels travaux, l’ameublement, l’enregistrement, les traductions, les frais bancaires et les prestations de tiers. Nos frais d’accompagnement immobilier annoncés sont de 0 €.'),('Par quoi commencer pour investir à distance ?','Indiquez votre budget total, votre apport, l’usage envisagé et votre horizon. Nous étudions ensuite les options et les démarches réalisables à distance avant tout engagement.')],
'sources':[('Code fiscal géorgien','https://matsne.gov.ge/en/document/view/1043717'),('Registre public géorgien : biens et cadastre','https://www.napr.gov.ge/en')]}
]
for p in pages:
 url=base+p['slug']+'.html';e=html.escape
 graph={'@context':'https://schema.org','@graph':[{'@type':'WebPage','@id':url+'#webpage','url':url,'name':p['title'],'description':p['desc'],'inLanguage':'fr','dateModified':'2026-11-19','isPartOf':{'@id':base+'#website'},'about':{'@id':base+'#organisation'},'mainEntity':{'@id':url+'#service'}},{'@type':'Service','@id':url+'#service','name':p['title'],'url':url,'description':p['lead'],'provider':{'@id':base+'#organisation'},'areaServed':{'@type':'Country','name':'Georgia'},'availableChannel':{'@type':'ServiceChannel','serviceUrl':base+'#contact'}},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Vivre en Géorgie','item':base},{'@type':'ListItem','position':2,'name':p['title'],'item':url}]}]}
 schema=json.dumps(graph,ensure_ascii=False,separators=(',',':'));digest=base64.b64encode(hashlib.sha256(schema.encode()).digest()).decode()
 sections=''.join(f'<section id="etape-{n}"><h2>{e(title)}</h2>{body}</section>' for n,(title,body) in enumerate(p['sections']))
 qa=''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in p['qa'])
 related=''.join(f'<a href="{x["slug"]}.html">{e(x["title"])}</a>' for x in pages if x!=p)
 sources=''.join(f'<li><a href="{e(href)}" rel="noopener noreferrer">{e(label)}</a></li>' for label,href in p['sources'])
 toc=''.join(f'<a href="#etape-{n}">{e(title)}</a>' for n,(title,body) in enumerate(p['sections']))
 doc=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'sha256-{digest}'; style-src 'self'; img-src 'self'; font-src 'self'; base-uri 'none'; object-src 'none'; form-action 'none'"><meta name="referrer" content="no-referrer"><title>{e(p['title'])} | Vivre en Géorgie</title><meta name="description" content="{e(p['desc'])}"><meta name="robots" content="index,follow,max-image-preview:large,max-snippet:-1"><link rel="canonical" href="{url}"><link rel="icon" href="assets/brand/monogram.svg" type="image/svg+xml"><link rel="stylesheet" href="services.css?v=1"><meta name="theme-color" content="#102637"><meta property="og:type" content="website"><meta property="og:site_name" content="Vivre en Géorgie"><meta property="og:title" content="{e(p['title'])}"><meta property="og:description" content="{e(p['desc'])}"><meta property="og:url" content="{url}"><meta property="og:image" content="{base}images/batumi-real.png"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">{schema}</script></head><body><a class="skip" href="#contenu">Aller au contenu</a><header><a class="brand" href="/"><img src="assets/brand/monogram.svg" width="42" height="42" alt=""><span>Vivre en <strong>Géorgie.</strong></span></a><a class="button" href="/#contact">Parlons de votre projet ↗</a></header><main id="contenu"><nav class="breadcrumb" aria-label="Fil d’Ariane"><a href="/">Accueil</a> / Accompagnement</nav><div class="intro"><p class="eyebrow">{p['tag']}</p><h1>{e(p['title'])}</h1><p class="lead">{e(p['lead'])}</p><p class="byline">Vivre en Géorgie · vivreengeorgie.com<br>Mis à jour le <time datetime="2026-11-19">19 novembre 2026</time></p></div><div class="layout"><aside><nav aria-label="Dans cette page"><p class="eyebrow">DANS CETTE PAGE</p>{toc}<a href="#questions">Questions fréquentes</a></nav></aside><div class="content">{sections}<section id="questions"><h2>Vos questions, avant de commencer.</h2>{qa}</section><section class="sources"><h2>Sources et périmètre</h2><p>Cette page présente notre accompagnement. Les conditions propres à votre dossier sont vérifiées avec les professionnels compétents ; les sources officielles restent la référence pour les règles applicables.</p><ul>{sources}</ul></section><section class="contact"><p class="eyebrow">VOTRE PROCHAINE ÉTAPE</p><h2>Préparons votre projet.</h2><p>Décrivez votre objectif, votre horizon et votre première question. Nous pourrons préciser l’accompagnement adapté.</p><a class="button" href="/#contact">Préparer mon message ↗</a></section><nav class="related" aria-label="Autres accompagnements">{related}</nav></div></div></main><footer><a href="/">Vivre en Géorgie · vivreengeorgie.com</a><a href="mentions-legales.html">Informations légales</a></footer></body></html>'''
 (R/(p['slug']+'.html')).write_text(doc,encoding='utf-8')
urls=[base]+[base+p['slug']+'.html' for p in pages]
(R/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>{u}</loc><lastmod>2026-11-19</lastmod></url>\n' for u in urls)+'</urlset>\n',encoding='utf-8')
p=R/'llms.txt';s=p.read_text(encoding='utf-8');s+='\n## Pages de services détaillées\n'+''.join(f'- [{x["title"]}]({base}{x["slug"]}.html): {x["desc"]}\n' for x in pages);p.write_text(s,encoding='utf-8')
